"""Authored short dialogue variants; merges keys without replacing other content."""
import json
from pathlib import Path
root = Path(__file__).resolve().parents[2] / 'src/main/resources/assets/dynasty/lang'
# Two extra first-meeting lines and four ordinary lines per existing role.
rows = {
'lao_chen': [('进门收好刀，炉边不许打闹。','Sheathe your blade inside. No roughhousing by the forge.'),('要修兵器，先让我看看裂口。','If your weapon needs repair, let me inspect its cracks.'),('锤声一停，这条街都冷清了。','When my hammer stops, the street falls quiet.'),('好钢也怕胡乱使劲。','Even fine steel suffers from careless use.'),('别急，火候没到，催也没用。','Be patient. Steel cannot be hurried.'),('炉前暖和，烤火别挡着风箱。','Warm yourself here, but leave the bellows clear.')],
'han_chong': [('这座烽火台，我守了半辈子。','I have guarded this watchtower for half my life.'),('若拾到阵亡弟兄的名册，交给我。','Bring me any roster of the fallen that you find.'),('巡夜别走谷底，那里藏得住人。','Keep out of the ravine at night. It hides ambushes.'),('刀可磨，断了的戟却接不回那一年。','A blade can be sharpened. My broken halberd cannot mend the past.'),('别轻看一声号角，那是活人的归路。','A horn call can lead survivors home.'),('风里没有喊杀声，便算个好日子。','A day without battle cries on the wind is a good day.')],
'qingxuanzi': [('竹林里无官无民，坐下便是客。','In this grove, titles mean nothing. Sit and be my guest.'),('路若走急了，先喝口茶。','If the road has hurried you, take a sip of tea.'),('这盘棋不争输赢，只等风落。','This game has no winner. We wait for the wind to settle.'),('雨打竹叶，也是一篇文章。','Rain upon bamboo is a poem of its own.'),('山里小径多，记住回头时的树。','The mountain has many paths. Remember the trees behind you.'),('四象各归其位，才有安稳天地。','Only when the four guardians return to their places can the world rest.')],
'baibao_jin': [('远路来的吧？我的货都经得住看。','You have traveled far. My goods welcome inspection.'),('价钱写在这里，喜欢再买。','The prices are here. Buy only what pleases you.'),('铜铃一响，生意就来了。','When my copper bell rings, business follows.'),('古物有旧伤，买前看仔细。','Antiques bear old scars. Inspect them before buying.'),('雨再大，也不能湿了账本。','Whatever the rain, my ledger must stay dry.'),('走南闯北，最值钱的还是信用。','After all my travels, trust remains my finest possession.')],
'a_ji': [('（攥紧麻绳，退到门后。）','(Clutches a cord and steps behind the door.)'),('（指着远处的荒坟，摇头。）','(Points to the distant graves and shakes his head.)'),('（听见脚步，慌忙捂住耳朵。）','(Hears footsteps and hurriedly covers his ears.)'),('（把一小块干粮藏进衣襟。）','(Hides a small piece of dried food in his coat.)'),('（看了看天空，又缩回阴影里。）','(Glances at the sky, then retreats into shadow.)'),('（笨拙地抱拳，眼神稍稍安定。）','(Offers an awkward salute, a little calmer.)')],
'hei_po': [('闻着苦味就怕了？还没尝呢。','Afraid of the bitter smell? You have not tasted it yet.'),('要药就拿材料来，别拿空话。','Bring ingredients for medicine, not empty promises.'),('瓶口盖紧，里面的东西会认路。','Seal those jars. Their contents know the way out.'),('一味药多半钱，也能变成毒。','Half a measure too much can turn medicine into poison.'),('水边的草，采前先看叶背。','Look beneath the leaves before gathering waterside herbs.'),('这炉熬好了，你站远些。','This brew is ready. Stand back.')],
'cao_chengfu': [('神道上莫喧哗，先整衣冠。','Quiet on the sacred path. Straighten your clothes.'),('陵里机关多，莫伸手乱碰。','The tomb holds many mechanisms. Touch nothing carelessly.'),('灯不能熄，这是祖上传下的规矩。','The lamps must never go out. So the old rule commands.'),('杂家守的是门，也是旧朝的体面。','I guard this gate and the dignity of the old court.'),('碑上姓名，不容后人涂改。','The names upon these stones are not yours to alter.'),('夜深了，脚步放轻。','Night is deep. Tread softly.')],
'hong_ling': [('篮里有花，要挑一枝吗？','There are flowers in my basket. Would you like one?' ),('看得这样仔细，倒叫人难为情。','Such close inspection makes me shy.'),('月下的影子，总比人长些。','Shadows always seem longer beneath the moon.'),('这花不沾露水，信不信随你。','These flowers gather no dew. Believe it if you wish.'),('村里的旧事，我记不太清了。','I remember little of the village past.'),('别往身后看，风凉。','Do not look behind you. The wind is cold.')],
'chu_nongyu': [('脚步轻些，我听得见。','Tread softly. I can hear you.'),('琴弦未整，先容我试一个音。','The strings are not ready. Let me test a note.'),('断弦有断弦的声，人也一样。','A broken string has its own voice. So do people.'),('风吹得急，今日不奏急曲。','The wind is hurried. Today I play no hurried tune.'),('我看不见山，却听得见泉。','I cannot see the mountain, but I hear its spring.'),('别把手放在弦上，它怕生。','Keep your hands from the strings. They are shy.')],
'xiaoyuanzi': [('我认得山上的草，可厉害了！','I know the mountain herbs. I am quite good at it!' ),('别踩那株，明天就能采了。','Do not step on that plant. It will be ready tomorrow.'),('师父说，挖药要给根留条路。','My teacher says to leave roots room to grow.'),('这个药篓比我还沉。','This herb basket feels heavier than I am.'),('下雨了，草叶上都有小灯。','When it rains, tiny lamps shine on every leaf.'),('你走慢点，我腿短。','Walk slowly. My legs are short.')],
'mo_jizi': [('先看手，后谈价，别碰齿轮。','Look at my work before discussing price. Leave the gears alone.'),('这条铁臂，比有些活人懂事。','This iron arm is more sensible than some living people.'),('轴偏一线，整架机器都要散。','A crooked axle can undo the whole machine.'),('木甲犬不吃饭，却也得养护。','A wooden hound needs no food, but it still needs care.'),('机关没有忠奸，握柄的人才有。','Machines have no loyalties. Their operators do.'),('旧城的铜响，我到现在还记得。','I still remember the copper sounds of the old city.')],
'sai_banxian': [('不问姓名，先坐下。','No names needed. Sit down first.'),('卦钱随缘，话却不能随便信。','The fee is yours to choose. Belief should be chosen more carefully.'),('吉凶都写在路上，卦里只见一角。','Fortune lies along the road. A reading shows only a corner.'),('天要落雨，幡先知道。','My banner knows the rain before it falls.'),('你心里有事，比铜钱响得大。','Your worry speaks louder than these coins.'),('避得了一阵风，避不了一辈子路。','You may shelter from a gust, but not from a lifetime of roads.')],
'ba_tu': [('弓别对着人，这里是猎户的规矩。','Never point a bow at a person. That is our rule.'),('雪地上的脚印，比问话可靠。','Tracks in snow answer more reliably than words.'),('兽也要过冬，别把一片林子猎空。','Animals must survive winter too. Never empty a forest.'),('火堆留点余炭，夜里冷。','Leave embers in the fire. The night is cold.'),('箭羽湿了，百步也会走偏。','A damp fletching can spoil a fine shot.'),('山上起白风了，今日别赶远路。','White winds gather above. Travel no farther today.')],
'yan_chifeng': [('我不问来路，只问你剑指何人。','I ask not where you came from, but whom your sword threatens.'),('要找妖，先听听村里人的话。','To find a demon, first hear the villagers.'),('磨剑磨的是刃，别把心也磨薄了。','Sharpen the blade without wearing down your heart.'),('斗笠遮雨，遮不了亏心事。','A hat shelters rain, not a guilty conscience.'),('路过三村，先看看烟火还在不在。','When passing villages, check whether their hearths still burn.'),('酒留给归来的人，出门前别喝。','Save the wine for your return. Drink none before setting out.')],
'huang_laohan': [('上船坐稳，手莫探进水里。','Sit firmly aboard. Keep your hands out of the water.'),('船钱好说，水下的规矩难说。','The fare is simple. The rules beneath the water are not.'),('看水纹，就知道底下有没有东西。','The ripples reveal whether something waits below.'),('老竹篙用了三十年，还没断。','This bamboo pole has served thirty years without breaking.'),('夜里听见叫名字，别答应。','If a voice calls your name at night, do not answer.'),('岸近了，等我把船拴住再下。','We near shore. Wait until I tie the boat before leaving.')],
}
for locale, index in [('zh_cn',0),('en_us',1)]:
    path = root / f'{locale}.json'
    data = json.loads(path.read_text())
    for role, values in rows.items():
        for suffix, pair in zip(['first_2','first_3','ordinary_2','ordinary_3','ordinary_4','ordinary_5'],values):
            data[f'cod3.dynasty.npc.{role}.{suffix}'] = pair[index]
    path.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
